SELECT issue_key, status, status_category, status_since
FROM issue_state_known_at(TIMESTAMP '2014-08-01 21:01', TIMESTAMP '2014-08-02 03:09')
WHERE issue_key = 'RAVE-1175';

SELECT issue_key, status, status_category, status_since
FROM issue_state_known_at(TIMESTAMP '2012-10-29 04:32', TIMESTAMP '2012-10-31 19:54')
WHERE issue_key = 'RAVE-729';

SELECT s.subject, s.id, s.ref, s.status, s.status_category, s.assignee, s.priority, s.resolution, s.priority_since, s.assignee_since, s.status_since
FROM issue_state_at('apache-tajo', TIMESTAMP '2017-07-26 07:22') s
WHERE s.ref = 'TAJO-1996' OR s.id = 'TAJO-1996' OR s.subject LIKE '%1996%';

WITH r AS (
  SELECT * FROM relations_at('apache-rave', TIMESTAMP '2015-01-09 18:01')
),
related AS (
  SELECT src AS other, rel, dst AS anchor FROM r WHERE dst LIKE '%RAVE-194%' OR dst LIKE '%:194'
  UNION ALL
  SELECT dst AS other, rel, src AS anchor FROM r WHERE src LIKE '%RAVE-194%' OR src LIKE '%:194'
)
SELECT * FROM related;

SELECT subject, id, ref, summary, status, status_category, resolution
FROM issue_state_at('apache-rave', TIMESTAMP '2015-01-09 18:01')
WHERE ref = 'RAVE-194' OR id LIKE '%194%';

SELECT ref, status, status_category, resolution
FROM issue_state_at('apache-rave', TIMESTAMP '2015-01-09 18:01')
WHERE ref IN ('RAVE-96', 'RAVE-676');

SELECT subject, id, ref, status, status_category, resolution
FROM issue_state_at('apache-rave', TIMESTAMP '2015-01-09 18:01')
WHERE subject IN ('issue:RAVE-96', 'issue:RAVE-676');

SELECT subject, id, ref, summary, status, status_category, resolution
FROM issue_state_at('apache-rave', TIMESTAMP '2013-12-29 18:07')
WHERE ref = 'RAVE-10' OR id = 'RAVE-10';

SELECT s.id, s.ref, s.status, s.status_category, s.assignee, s.priority, s.resolution, s.issue_type
FROM issue_state_at('apache-rave', TIMESTAMP '2012-12-13 20:21') s
WHERE s.ref = 'RAVE-509' OR s.id = '509';

SELECT issue_key, status, status_category, status_since
FROM issue_state_known_at(TIMESTAMP '2014-08-01 21:01', TIMESTAMP '2014-08-02 03:09')
WHERE issue_key = 'RAVE-1175';

SELECT issue_key, status, status_category, status_since
FROM issue_state_known_at(TIMESTAMP '2012-10-29 04:32', TIMESTAMP '2012-10-31 19:54')
WHERE issue_key = 'RAVE-729';

SELECT subject, status, status_category, status_since, ref
FROM issue_state_at('apache-tajo', TIMESTAMP '2015-09-08 15:19')
WHERE ref = 'TAJO-1511' OR subject = 'issue:1511';

SELECT subject, id, ref, summary, status, status_category
FROM issue_state_at('apache-tajo', TIMESTAMP '2015-09-08 15:19')
WHERE ref LIKE '%1511%' OR id LIKE '%1511%' OR summary LIKE '%1511%';

SELECT v.subject, v.verdict
FROM blocked_verdicts('apache-tajo', TIMESTAMP '2015-09-08 15:19') v
WHERE v.subject = 'issue:TAJO-1511';

SELECT r.src, r.dst, r.rel, r.valid_from, r.valid_to
FROM relations_at('apache-rave', TIMESTAMP '2012-12-03 06:39') r
WHERE r.rel = 'blocks';

SELECT issue_key, status, status_category, status_since
FROM issue_state_known_at(TIMESTAMP '2020-03-18 21:48', TIMESTAMP '2020-03-18 21:48')
WHERE issue_key IN ('TAJO-2128', 'TAJO-825');

WITH t AS (SELECT TIMESTAMP '2014-04-29 12:47' AS t),
target AS (
  SELECT subject FROM issue_state_at('apache-rave', TIMESTAMP '2014-04-29 12:47') WHERE ref = 'RAVE-164'
),
rels AS (
  SELECT r.* FROM relations_at('apache-rave', TIMESTAMP '2014-04-29 12:47') r
  WHERE r.src IN (SELECT subject FROM target) OR r.dst IN (SELECT subject FROM target)
)
SELECT * FROM rels;
